function bell(){const p=$('#bp');if(p.style.display=='block'){p.style.display='none';return}p.style.display='block';p.innerHTML=`<b>Notifications</b>${S.notifs.slice(0,6).map(n=>`<div style="padding:9px 0;border-bottom:1px solid var(--line)" class="mu">${esc(n.m)} <span style="float:right">${n.t}</span></div>`).join('')}`}
