function home(){const q=S.q,pk=matches(q).slice(0,4),near=S.items.filter(i=>i.live&&i.ok&&dist(i)<=5),ns=near.sort((a,b)=>dist(a)-dist(b)).slice(0,4),cm=impactNums();
return`<section class="hero"><div><span class="pill">${ic('leaf').replace('class="ic"','class="ic" style="width:14px;height:14px"')} Chennai pilot · hyperlocal clothing sharing</span><h1 style="margin:14px 0">Why buy it for one day?</h1><p class="mu" style="font-size:17px;margin-bottom:22px">Find beautiful clothes nearby, wear them for your occasion, and return them when you're done.</p><div class="row"><button class="btn" onclick="go('find')">Find an Outfit</button><button class="btn o" onclick="S.mode='list';go('list')">Earn From Your Wardrobe</button></div><p class="mu" style="margin-top:22px;font-weight:500">We are not selling clothes. We are increasing the utilization of clothes that already exist.</p></div><div class="hv"><div style="left:0;top:20px;transform:rotate(-5deg)">${art(S.items[0])}</div><div style="right:0;top:0;transform:rotate(4deg)">${art(S.items[2])}</div><div style="left:28%;bottom:0">${art(S.items[4])}</div></div></section>
<section class="sec"><h2>Find what you need. Nearby.</h2><div class="card"><label for="ai">What are you dressing for?</label><div class="row"><input id="ai" style="flex:1;min-width:220px" placeholder="e.g. I have a college farewell next Friday and want something elegant under ₹700" onkeydown="if(event.key=='Enter')ask()"><button class="btn" onclick="ask()">✦ Smart Match</button></div><div id="aie" class="err"></div><div class="row" style="margin-top:14px"><span class="mu">Popular occasions</span>${occChips()}</div></div></section>
<section class="sec"><div class="row sp mb"><div><h2>AI Picks For You</h2><p class="mu">Ranked for ${q.occ}, size ${q.size}, under ${fmt(q.budget)} · <a href="#" onclick="go('find');return false" style="color:var(--green)">change</a></p></div></div><div class="grid">${pk.map(m=>card(m.it,m.sc)).join('')||empty()}</div></section>
<section class="sec"><h2>Available Near You</h2><p class="mu mb">${near.length} outfits within 5 km of ${S.me.area}</p><div class="grid">${ns.map(i=>card(i)).join('')}</div></section>
<section class="sec"><h2>How CIRCLOSET Works</h2><div class="g4" style="margin-top:12px">${['Tell us your occasion','AI finds your match','Rent nearby','Wear it','Return it'].map((t,i)=>`<div class="card"><div class="big">${i+1}</div><b>${t}</b></div>`).join('')}</div></section>
<section class="sec card" style="background:var(--brand);color:var(--btxt)"><h2>Your unused clothes can earn too.</h2><p style="margin:6px 0 16px;opacity:.85">Most wardrobes hold outfits worn once. List them and earn on every rental — with deposits and verified renters protecting you.</p><button class="btn" style="background:var(--btxt);color:var(--brand)" onclick="S.mode='list';go('list')">List Your Clothes</button></section>
<section class="sec"><h2>Buy less → Share more → Earn → Reduce waste</h2><p class="mu mb">Estimated impact based on configurable assumptions (demo pilot data).</p>${impactCards(cm)}</section>`}
const empty=()=>`<div class="card" style="grid-column:1/-1;text-align:center;padding:40px"><h3>Nothing perfect nearby yet.</h3><p class="mu" style="margin:6px 0 16px">Try expanding your distance or budget.</p><button class="btn" onclick="go('find')">Adjust search</button></div>`;
function ask(){const t=$('#ai').value.trim();if(t.length<6){$('#aie').textContent='Tell us a little more — e.g. the occasion, your budget and the date.';return}const x=parse(t);if(!x.occ){$('#aie').textContent='We couldn\'t spot the occasion. Try words like wedding, interview, party or farewell.';return}
S.q=Object.assign(S.q,{occ:x.occ,style:x.style||'Any',budget:x.budget||S.q.budget,start:x.date||S.q.start,g:x.g||'Any',size:x.size||S.q.size},{ex:{Occasion:x.occ,Style:x.style||'Any',Budget:x.budget?fmt(x.budget):'Not stated',Date:x.date?dfl(x.date):'Not stated'}});go('results')}
function parse(t){t=t.toLowerCase();const x={},oc=[[/wedding|marriage|reception/,'Wedding'],[/interview/,'Interview'],[/pongal|diwali|navaratri|onam|festival/,'Festival'],[/photo|shoot/,'Photoshoot'],[/farewell|college|cultural|fest\b/,'College Event'],[/party|birthday|cocktail/,'Party'],[/formal|corporate|conference/,'Formal Event']];
for(const[r,o]of oc)if(r.test(t)){x.occ=o;break}
const st=t.match(/elegant|traditional|modern|formal/);if(st)x.style=st[0][0].toUpperCase()+st[0].slice(1);
const b=t.match(/(?:under|below|within|budget(?: of)?|upto|up to)\s*(?:₹|rs\.?)?\s*(\d[\d,]*)/)||t.match(/(?:₹|rs\.?)\s*(\d[\d,]*)/);if(b)x.budget=+b[1].replace(/,/g,'');
const sz=t.match(/\bsize\s*(xxl|xl|xs|s|m|l)\b/);if(sz)x.size=sz[1].toUpperCase();if(/\b(men|boy|groom)\b/.test(t))x.g='Men';if(/women|girl|saree|lehenga|bride/.test(t))x.g='Women';
const days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'],dn=days.findIndex(d=>t.includes(d)),n=new Date().getDay();
if(dn>=0){let k=(dn-n+7)%7||7;x.date=iso(k)}else if(/tomorrow/.test(t))x.date=iso(1);else if(/today/.test(t))x.date=iso(0);else if(/weekend/.test(t))x.date=iso((6-n+7)%7||7);else{const m=t.match(/in (\d+) days/);if(m)x.date=iso(+m[1])}return x}
function sel(id,arr,v,l){return`<div><label for="${id}">${l}</label><select id="${id}">${arr.map(a=>`<option ${a==v?'selected':''}>${a}</option>`).join('')}</select></div>`}
function stepper(n){return`<div class="stp">${['Find','Match','Book','Wear','Return'].map((s,i)=>`<div class="${i<n?'on':''}">${i+1}. ${s}</div>`).join('')}</div>`}
function find(){const q=S.q;return`${stepper(1)}<h2>What are you dressing for?</h2><p class="mu mb">Tell us the details — our matching engine ranks nearby outfits and explains every score.</p><div class="card"><div class="f">${sel('q1',Object.values(OCC),q.occ,'Occasion')}${sel('q2',['Any','Women','Men'],q.g,'Category')}${sel('q3',['Any',...SZ],q.size,'Size')}${sel('q4',['Any','Elegant','Traditional','Modern','Formal'],q.style,'Preferred style')}${sel('q5',['Any','Red','Green','Blue','Gold','Pink','Neutral','Black'],q.color,'Colour')}<div><label for="q6">Total rent budget (₹)</label><input id="q6" type="number" min="100" step="50" value="${q.budget}"></div><div><label for="q7">Rental date</label><input id="q7" type="date" min="${iso(0)}" value="${q.start}"></div>${sel('q8',[1,2,3,4,5,7],q.days,'Duration (days)')}${sel('q9',[1,3,5,10],q.max,'Max distance (km)')}${sel('q10',Object.keys(AREAS),S.me.area,'Your area')}</div><div id="fe" class="err"></div><button class="btn" style="margin-top:18px" onclick="runFind()">✦ Find my match</button></div>`}
function runFind(){const g=id=>$('#'+id).value,b=+g('q6');if(!b||b<100){$('#fe').textContent='Please enter a budget of at least ₹100.';return}if(!g('q7')||g('q7')<iso(0)){$('#fe').textContent='Please choose a rental date from today onwards.';return}
S.me.area=g('q10');S.q={occ:g('q1'),g:g('q2'),size:g('q3'),style:g('q4'),color:g('q5'),budget:b,start:g('q7'),days:+g('q8'),max:+g('q9'),ex:null};go('results')}
function results(){const q=S.q,m=matches(q),e=addd(q.start,q.days-1),top=m[0];
return`${stepper(2)}<div class="row sp mb"><div><h2>${m.length} matching outfits within ${q.max} km</h2><p class="mu">${q.occ} · size ${q.size} · ${fmt(q.budget)} · ${dfl(q.start)}${q.days>1?' – '+df(e):''} · near ${S.me.area}</p></div><button class="btn o s" onclick="go('find')">Edit search</button></div>
${q.ex?`<div class="card mb" style="background:var(--gl)"><b>✦ What we understood</b><div class="row" style="margin-top:8px">${Object.entries(q.ex).map(([k,v])=>`<span class="pill c">${k} → ${esc(v)}</span>`).join('')}</div></div>`:''}
${top?`<div class="card mb g2" style="padding:0;overflow:hidden"><div style="cursor:pointer" onclick="go('item',${top.it.id})">${art(top.it)}</div><div style="padding:22px"><span class="pill">Best match</span><h2 style="margin-top:8px">${esc(top.it.t)}</h2><p class="mu mb">${fmt(top.it.p)}/day · ${top.it.area} · ${own(top.it).n}</p>${factors(top.sc,top.it,q)}<button class="btn" onclick="go('item',${top.it.id})">View outfit</button></div></div><h3 class="mb">More matches</h3><div class="grid">${m.slice(1).map(x=>card(x.it,x.sc)).join('')||''}</div>`:empty()}`}
function grid(){const f=S.f,q=S.q;let L=S.items.filter(i=>i.live&&i.ok&&(!f.ty||i.ty=='both'||i.ty==f.ty)&&(!f.txt||(i.t+i.b+i.c).toLowerCase().includes(f.txt.toLowerCase()))&&(!f.cat||i.c==f.cat)&&(!f.occ||i.occ.includes(f.occ))&&(!f.size||i.s==f.size||i.s=='Free')&&dist(i)<=f.dist&&(!f.bud||(f.bud=='a'?i.p<=500:f.bud=='b'?i.p>500&&i.p<=1000:i.p>1000))&&(!f.start||avail(i,f.start,f.start)));
const sc=i=>score(i,{...q,start:f.start||q.start});const M={match:(a,b)=>sc(b).t-sc(a).t,price:(a,b)=>a.p-b.p,distance:(a,b)=>dist(a)-dist(b),rating:(a,b)=>b.r-a.r,newest:(a,b)=>b.id-a.id};L.sort(M[f.sort]);
$('#gr').innerHTML=L.length?L.map(i=>card(i,f.sort=='match'?sc(i):null)).join(''):empty();$('#cn').textContent=L.length+' outfits'+(f.start?' available on '+df(f.start):'')+' within '+f.dist+' km'}
function setF(k,v){S.f[k]=k=='dist'?+v:v;save();grid()}
function explore(){const f=S.f,o=(id,l,arr,k,pl)=>`<div><label for="${id}">${l}</label><select id="${id}" onchange="setF('${k}',this.value)"><option value="">${pl}</option>${arr.map(a=>`<option value="${Array.isArray(a)?a[0]:a}" ${(Array.isArray(a)?a[0]:a)==f[k]?'selected':''}>${Array.isArray(a)?a[1]:a}</option>`).join('')}</select></div>`;
return`<h2>Explore outfits near ${S.me.area}</h2><p id="cn" class="mu mb"></p><div class="card mb"><div class="f"><div><label for="ft">Search</label><input id="ft" value="${esc(f.txt)}" placeholder="Anarkali, blazer, Manyavar…" oninput="setF('txt',this.value)"></div>${o('fc','Category',CATS,'cat','All')}${o('fo','Occasion',Object.values(OCC),'occ','All')}${o('fs','Size',SZ,'size','All')}${o('fb','Budget / day',[['a','₹200–₹500'],['b','₹500–₹1,000'],['c','₹1,000–₹2,000']],'bud','Any')}<div><label for="fd">Distance</label><select id="fd" onchange="setF('dist',this.value)">${[1,3,5,10].map(d=>`<option value="${d}" ${d==f.dist?'selected':''}>${d} km</option>`).join('')}</select></div><div><label for="fa">Available on</label><input id="fa" type="date" min="${iso(0)}" value="${f.start}" onchange="setF('start',this.value)"></div><div><label for="fr">Sort by</label><select id="fr" onchange="setF('sort',this.value)">${[['match','AI Match'],['price','Price'],['distance','Distance'],['rating','Rating'],['newest','Newest']].map(a=>`<option value="${a[0]}" ${a[0]==f.sort?'selected':''}>${a[1]}</option>`).join('')}</select></div></div></div><div id="gr" class="grid"></div>`}
function itemPg(){const it=S.items.find(i=>i.id==S.param);if(!it)return empty();const q=S.q,sl=S.sel[it.id]||(S.sel[it.id]={s:q.start,d:q.days}),e=addd(sl.s,sl.d-1),o=own(it),av=avail(it,sl.s,e),sc=score(it,{...q,start:sl.s,days:sl.d}),fv=S.favs.includes(it.id);
const sim=matches({...q,start:sl.s,days:sl.d}).filter(m=>m.it.id!=it.id).slice(0,5);const nxt=it.blk.find(x=>x[1]>=iso(0));
return`${stepper(3)}<div class="g2" style="align-items:start"><div class="card" style="padding:0;overflow:hidden">${art(it)}</div><div><span class="pill">${it.c} · ${it.b}</span><h1 style="font-size:32px;margin:8px 0">${esc(it.t)}</h1><div class="row"><span class="big">${fmt(it.p)}</span><span class="mu">/ day</span><span class="mu">${stars(it.r)} (${it.n} rentals)</span></div><p class="mu">Refundable security deposit <b style="color:var(--ink)">${fmt(it.d)}</b> · ~${dist(it)} km away · ${it.area}</p>
<div class="g4" style="margin:16px 0"><div class="card" style="padding:12px"><span class="mu">Size</span><br><b>${it.s}</b> · Regular fit</div><div class="card" style="padding:12px"><span class="mu">Condition</span><br><b>${it.cd}</b></div><div class="card" style="padding:12px"><span class="mu">Last cleaned</span><br><b>${it.clean} days ago</b></div><div class="card" style="padding:12px"><span class="mu">Cleanliness</span><br><b style="color:var(--green)">✓ Verified</b></div></div>
<div class="mb"><span class="mu">Suitable for</span><div class="row" style="margin-top:6px">${it.occ.map(x=>`<span class="pill c">${x}</span>`).join('')}</div></div>
<div class="card mb"><div class="row sp"><div><b>${esc(o.n)}</b><div class="mu">Owner · ${o.ret}% on-time returns</div></div><span class="pill ${o.v?'':'w'}">${o.v?'✓ Identity Verified':'Verification pending'}</span></div><div class="row" style="margin-top:10px"><span class="pill">✓ Highly Rated</span><span class="pill">✓ Cleanliness Checked</span>${o.ret>=95?'<span class="pill">✓ Reliable Return History</span>':''}</div><p class="mu" style="margin-top:10px">${ic('shield').replace('class="ic"','class="ic" style="width:14px;height:14px"')} Exact address stays private. Pickup point is shared only after booking is confirmed.</p></div>
<div class="card mb"><div class="f"><div><label for="d1">Start date</label><input id="d1" type="date" min="${iso(0)}" value="${sl.s}" onchange="S.sel[${it.id}].s=this.value||iso(0);save();render(1)"></div>${sel2('d2',sl.d)}</div><p class="mu" style="margin-top:8px">${nxt?'Blocked by other bookings: '+df(nxt[0])+' – '+df(nxt[1]):'Open calendar'} · Return by ${df(e)}, 8 PM</p>${av?`<p style="color:var(--green);font-weight:600;margin-top:6px">✓ Available ${df(sl.s)}${sl.d>1?' – '+df(e):''} · Rent ${fmt(it.p*sl.d)}</p>`:`<div class="al" style="margin-top:8px">This outfit was just booked for those dates. Here are ${sim.length} similar matches.</div>`}</div>
<div class="row"><button class="btn" ${av?'':'disabled'} onclick="startCo(${it.id})">Rent Now</button><button class="btn o" onclick="fav(${it.id})">${fv?'♥ Saved':'♡ Save'}</button><button class="btn o" onclick="T.msg=T.msg?'':'1';render(1)">Ask Owner</button></div>
${T.msg?`<div class="card" style="margin-top:12px"><label for="mg">Message to ${esc(o.n)}</label><input id="mg" maxlength="200" placeholder="Is a blouse included?"><button class="btn s" style="margin-top:8px" onclick="sendMsg('${esc(o.n)}')">Send</button></div>`:''}</div></div>
<div class="g2 sec"><div class="card">${factors(sc,it,{...q})}</div><div class="card"><h3>Rental terms & damage policy</h3><p class="mu" style="margin-top:8px">• Digital rental agreement signed at checkout.<br>• Return on time to receive the full deposit; late returns are charged one extra day's rent per day.<br>• Minor wear is expected. Damage is assessed by the owner with photo evidence and reviewed by CIRCLOSET support before any deposit adjustment.<br>• Report any issue from the Bookings page.</p></div></div>
${av?'':`<div class="sec"><h3 class="mb">Similar matches</h3><div class="grid">${sim.map(m=>card(m.it,m.sc)).join('')}</div></div>`}`}
const sel2=(id,v)=>`<div><label for="${id}">Duration</label><select id="${id}" onchange="S.sel[S.param].d=+this.value;save();render(1)">${[1,2,3,4,5,7].map(d=>`<option value="${d}" ${d==v?'selected':''}>${d} day${d>1?'s':''}</option>`).join('')}</select></div>`;
function sendMsg(n){const v=$('#mg').value.trim();if(!v){toast('Type a message first');return}T.msg='';notif('You messaged '+n+': "'+v.slice(0,40)+'"');toast('Message sent to '+n);render(1)}
function calc(it,sl,ful){const rent=it.p*sl.d,rate=S.me.plus?S.cfg.feePlus:S.cfg.fee,fee=Math.round(rent*rate/100),del=ful=='delivery'&&!S.me.plus?S.cfg.del:0;return{rent,fee,del,dep:it.d,total:rent+fee+del+it.d,rate}}
function startCo(id){const it=S.items.find(i=>i.id==id),sl=S.sel[id];if(!avail(it,sl.s,addd(sl.s,sl.d-1))){toast('Not available for those dates');return}T.co={id,ful:'pickup',ag:0,fail:0,err:''};go('checkout',id)}
function checkout(){const c=T.co;if(!c)return go('explore'),'';const it=S.items.find(i=>i.id==c.id),sl=S.sel[c.id],k=calc(it,sl,c.ful),e=addd(sl.s,sl.d-1);
return`${stepper(3)}<h2>Checkout</h2><div class="g2" style="align-items:start"><div><div class="card mb"><h3>Pickup or delivery</h3><div style="margin-top:10px"><label style="font-weight:500"><input type="radio" name="fu" ${c.ful=='pickup'?'checked':''} onchange="T.co.ful='pickup';render(1)"> Pickup at a safe public point — Free</label><label style="font-weight:500;margin-top:8px"><input type="radio" name="fu" ${c.ful=='delivery'?'checked':''} onchange="T.co.ful='delivery';render(1)"> Delivery — ${S.me.plus?'<b>Free with Plus</b>':fmt(S.cfg.del)}</label></div></div>
<div class="card mb"><h3>Payment (mock)</h3><p class="mu mb">No real payment details are collected in this prototype.</p><select id="pm" aria-label="Payment method"><option>UPI</option><option>Debit / Credit card</option><option>Net banking</option></select><label style="font-weight:500;margin-top:12px"><input type="checkbox" ${c.fail?'checked':''} onchange="T.co.fail=this.checked"> Demo: simulate payment failure</label></div>
<label style="font-weight:500"><input type="checkbox" id="ag" ${c.ag?'checked':''} onchange="T.co.ag=this.checked"> I agree to the digital rental agreement, return deadline (${df(e)}, 8 PM) and damage policy.</label><div class="err" id="ce">${esc(c.err)}</div></div>
<div class="card"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div style="width:84px;border-radius:12px;overflow:hidden;flex:none">${art(it)}</div><div><b>${esc(it.t)}</b><div class="mu">${dfl(sl.s)}${sl.d>1?' – '+df(e):''} · ${sl.d} day${sl.d>1?'s':''}</div></div></div><table><tr><td>Rental (${fmt(it.p)} × ${sl.d})</td><td align="right">${fmt(k.rent)}</td></tr><tr><td>Platform fee (${k.rate}%)</td><td align="right">${fmt(k.fee)}</td></tr><tr><td>Delivery</td><td align="right">${k.del?fmt(k.del):'Free'}</td></tr><tr><td><b>Refundable Security Deposit</b><div class="mu">Returned after inspection</div></td><td align="right"><b style="color:var(--green)">${fmt(k.dep)}</b></td></tr><tr><td class="big">Total</td><td align="right" class="big">${fmt(k.total)}</td></tr></table><p class="mu mb">Buying new would cost about ${fmt(it.mrp)}. You save ${fmt(it.mrp-k.rent-k.fee)}.</p><button class="btn w" id="pb" onclick="pay()">Pay ${fmt(k.total)}</button></div></div>`}
function pay(){const c=T.co,it=S.items.find(i=>i.id==c.id),sl=S.sel[c.id];if(!$('#ag').checked){T.co.err='Please accept the rental agreement to continue.';return render(1)}
const b=$('#pb');b.disabled=true;b.textContent='Processing payment…';setTimeout(()=>{if(c.fail){T.co.err='Payment couldn\'t be completed. Your booking hasn\'t been created.';T.co.ag=1;render(1);return}
const e=addd(sl.s,sl.d-1);if(!avail(it,sl.s,e)){go('item',it.id);return}const k=calc(it,sl,c.ful),id='RW-'+(24130+S.bookings.length);
S.bookings.unshift({id,item:it.id,renter:'me',start:sl.s,end:e,days:sl.d,rent:k.rent,dep:k.dep,fee:k.fee,del:k.del,total:k.total,stage:0,created:iso(0),rv:0,ful:c.ful});notif('Booking '+id+' confirmed: '+it.t);T.co=null;go('confirm',id)},1100)}
function confirm(){const b=S.bookings.find(x=>x.id==S.param);if(!b)return go('bookings'),'';const it=S.items.find(i=>i.id==b.item),o=own(it);
return`${stepper(4)}<div class="card" style="max-width:640px;margin:0 auto"><div style="text-align:center"><div class="pill" style="font-size:14px">✓ Booking Confirmed</div><h2 style="margin-top:12px">${esc(it.t)} is yours</h2><p class="mu">Booking ID <b>${b.id}</b></p></div><table><tr><td>Rental period</td><td align="right">${dfl(b.start)} – ${dfl(b.end)}</td></tr><tr><td>Return deadline</td><td align="right">${df(b.end)}, 8:00 PM</td></tr><tr><td>${b.ful=='delivery'?'Delivery':'Pickup point'}</td><td align="right">${b.ful=='delivery'?'To your address, morning of '+df(b.start):esc(PICK[it.area])}</td></tr><tr><td>Owner</td><td align="right">${esc(o.n)} · +91 98•••• ${1000+it.id*37%9000}</td></tr><tr><td>Refundable deposit</td><td align="right" style="color:var(--green)"><b>${fmt(b.dep)}</b></td></tr><tr><td>Total paid</td><td align="right"><b>${fmt(b.total)}</b></td></tr></table><p class="mu">Pickup details are revealed only after confirmation. Support: help@circloset.in</p><div class="row" style="margin-top:14px"><button class="btn" onclick="go('bookings')">Track rental</button><button class="btn o" onclick="go('home')">Back home</button></div></div>`}
function stepBar(s){return`<div class="tl">${STG.map((x,i)=>`<div class="${i<=s?'d':''}">${x}</div>`).join('')}</div>`}
function adv(id){const b=S.bookings.find(x=>x.id==id);b.stage++;const it=S.items.find(i=>i.id==b.item);
if(b.stage==6){notif('Deposit of '+fmt(b.dep-(b.hold||0))+' refunded for '+b.id);toast('Deposit refunded ✓')}else toast('Status: '+STG[b.stage]);save();render(1)}
function dmg(id){const b=S.bookings.find(x=>x.id==id),a=+$('#da'+id).value,n=$('#dn'+id).value.trim();if(!a||a<50||a>b.dep||n.length<5){toast('Enter an amount up to the deposit and a short description');return}
const it=S.items.find(i=>i.id==b.item),ev=$('#de'+id).files[0];S.issues.unshift({id:S.issues.length+2,b:b.id,item:it.t,by:own(it).n,note:n+(ev?' (evidence: '+ev.name+')':''),amt:a,dep:b.dep,st:'Open',pay:id});b.issue=1;b.hold=a;notif('Damage reported on '+b.id+' — under admin review');toast('Issue sent to CIRCLOSET admin');save();render(1)}
function bcard(b,ownerView){const it=S.items.find(i=>i.id==b.item);if(!it)return'';const days=nd(iso(0),b.end)-1,od=b.stage==3||(b.stage>=1&&b.stage<4&&b.end<=iso(0));
let act='';if(b.stage==-1)act=ownerView?`<button class="btn s g" onclick="reqAns('${b.id}',1)">Accept</button><button class="btn s o" onclick="reqAns('${b.id}',0)">Reject</button>`:'<span class="pill c">Awaiting owner</span>';
else if(b.issue&&b.stage==5)act='<span class="pill w">Issue under admin review</span>';
else if(b.stage==4)act=`<button class="btn s" onclick="adv('${b.id}')">Start inspection</button>`;
else if(b.stage==5)act=`<button class="btn s g" onclick="adv('${b.id}')">No damage · refund deposit</button><details><summary class="mu" style="cursor:pointer;margin-top:6px">Report damage</summary><div class="f" style="margin-top:8px"><input id="da${b.id}" type="number" placeholder="Deduction ₹" aria-label="Deduction amount"><input id="dn${b.id}" placeholder="Describe damage" aria-label="Damage description"><input id="de${b.id}" type="file" accept="image/*" aria-label="Upload evidence"></div><button class="btn s o" style="margin-top:8px" onclick="dmg('${b.id}')">Submit to admin</button></details>`;
else if(b.stage<4)act=`<button class="btn s o" onclick="adv('${b.id}')">${['Confirm pickup','Mark as in use','Return due','Confirm return'][b.stage]} (demo)</button>`;
const rev=!ownerView&&b.stage==6&&!b.rv?`<div style="margin-top:10px"><label>Rate the owner</label><div class="row">${[1,2,3,4,5].map(n=>`<button class="ch" onclick="review('${b.id}',${n})" aria-label="${n} stars">${'★'.repeat(n)}</button>`).join('')}</div></div>`:'';
return`<div class="card mb"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div style="width:90px;border-radius:12px;overflow:hidden;flex:none">${art(it)}</div><div style="flex:1"><div class="row sp"><b>${esc(it.t)}</b><span class="pill ${b.stage==6?'':b.stage==-1?'c':''}">${b.stage<0?'Requested':STG[b.stage]}</span></div><div class="mu">${b.id} · ${dfl(b.start)} – ${df(b.end)} · ${ownerView?'Renter '+esc(b.renter):'Owner '+esc(own(it).n)}</div><div class="mu">${ownerView?'You earn '+fmt(b.rent):'Total '+fmt(b.total)+' · Deposit '+fmt(b.dep)}</div></div></div>${b.stage>=0?stepBar(b.stage):''}${od?`<div class="al mb">Your return is due today.</div>`:b.stage>=0&&b.stage<3?`<p class="mu mb">Return countdown: ${days>=0?days+' day'+(days==1?'':'s'):'—'} until ${df(b.end)}, 8 PM</p>`:''}<div class="row">${act}</div>${rev}</div>`}
function review(id,n){const b=S.bookings.find(x=>x.id==id),it=S.items.find(i=>i.id==b.item);b.rv=1;S.reviews.push({b:id,n});it.r=+((it.r*it.n+n)/(it.n+1)).toFixed(2);it.n++;toast('Thanks for your review');save();render(1)}
function reqAns(id,ok){const b=S.bookings.find(x=>x.id==id);if(ok){b.stage=0;b.fee=Math.round(b.rent*.1);b.total=b.rent+b.dep+b.fee;notif('You accepted '+b.renter+"'s request "+b.id)}else{S.bookings=S.bookings.filter(x=>x.id!=id);notif('Request declined')}toast(ok?'Request accepted':'Request declined');save();render(1)}
function bookings(){const mine=S.bookings.filter(b=>b.renter=='me'),up=mine.filter(b=>b.stage<6),hi=mine.filter(b=>b.stage==6),sv=S.items.filter(i=>S.favs.includes(i.id)),im=impactNums(),rc=matches(S.q).slice(0,3);
return`${stepper(5)}<h2>My bookings</h2><p class="mu mb">Track every rental from pickup to deposit refund.</p>${up.map(b=>bcard(b)).join('')||`<div class="card mb"><b>No upcoming rentals.</b><p class="mu">Find an outfit for your next occasion.</p><button class="btn s" style="margin-top:10px" onclick="go('find')">Find an Outfit</button></div>`}<div class="g4 mb"><div class="card"><span class="mu">Impact generated</span><div class="big">${im.mine} reuse${im.mine==1?'':'s'}</div></div><div class="card"><span class="mu">Saved vs buying new</span><div class="big">${fmt(im.saved)}</div></div></div><h3 class="mb">Rental history</h3>${hi.map(b=>bcard(b)).join('')||'<p class="mu mb">Completed rentals appear here.</p>'}<h3 class="mb sec">Saved items</h3><div class="grid">${sv.map(i=>card(i)).join('')||'<p class="mu">Tap ♥ on any outfit to save it.</p>'}</div><h3 class="mb sec">AI recommendations</h3><div class="grid">${rc.map(m=>card(m.it,m.sc)).join('')}</div>`}
function impactNums(){const c=S.cfg,base=1284,done=S.bookings.filter(b=>b.stage>=4),mine=S.bookings.filter(b=>b.renter=='me'&&b.stage>=4),n=base+done.length,ear=S.bookings.filter(b=>b.stage>=4&&S.items.find(i=>i.id==b.item)?.o=='me').reduce((a,b)=>a+b.rent,0);
return{n,kg:Math.round(n*c.kg),w:Math.round(n*c.water),saved:mine.reduce((a,b)=>a+(S.items.find(i=>i.id==b.item).mrp-b.rent-b.fee),0),mine:mine.length,earned:ear,commSaved:Math.round(n*2150),commEarn:Math.round(n*640)}}
function impactCards(m){return`<div class="g4"><div class="card"><span class="mu">♻️ Clothing items reused</span><div class="big">${m.n.toLocaleString('en-IN')}</div></div><div class="card"><span class="mu">🌱 Est. textile waste avoided</span><div class="big">${m.kg.toLocaleString('en-IN')} kg</div></div><div class="card"><span class="mu">💧 Est. water footprint avoided</span><div class="big">${(m.w/1e5).toFixed(1)} lakh L</div></div><div class="card"><span class="mu">💰 Saved by renters</span><div class="big">${fmt(m.commSaved)}</div></div><div class="card"><span class="mu">💵 Earned by owners</span><div class="big">${fmt(m.commEarn)}</div></div></div>`}
function impact(){const m=impactNums(),c=S.cfg;return`<h2>Impact</h2><p class="mu mb">1 rental = 1 avoided new purchase. Community figures are demo pilot data; your bookings add to them live.</p>${impactCards(m)}<div class="g2 sec"><div class="card"><h3>Your contribution</h3><table><tr><td>Rentals completed as renter</td><td align="right"><b>${m.mine}</b></td></tr><tr><td>Saved vs buying new</td><td align="right"><b>${fmt(m.saved)}</b></td></tr><tr><td>Earned as owner</td><td align="right"><b>${fmt(m.earned)}</b></td></tr></table></div><div class="card"><h3>How we calculate impact</h3><p class="mu" style="margin-top:8px"><b style="color:var(--ink)">Estimated impact = rental uses × configurable avoided-purchase factor.</b><br>Textile waste = uses × ${c.kg} kg per garment.<br>Water footprint = uses × ${c.water.toLocaleString('en-IN')} L per garment.<br>Renter savings = est. retail price − rent − fee.<br><i>Estimated impact based on configurable assumptions — not scientifically exact. Factors are editable in Admin → Configuration.</i></p></div></div>`}
function wardrobe(){const mine=S.items.filter(i=>i.o=='me'),bs=S.bookings.filter(b=>mine.some(i=>i.id==b.item)),req=bs.filter(b=>b.stage==-1),act=bs.filter(b=>b.stage>=0&&b.stage<4),done=bs.filter(b=>b.stage>=4),earn=done.reduce((a,b)=>a+b.rent,0),ch=[420,780,510,960,1180,earn+540],mn=['May','Jun','Jul','Aug','Sep','Oct'],mx=Math.max(...ch);
return`<div class="row sp mb"><div><h2>My wardrobe</h2><p class="mu">Turn clothes you rarely wear into income.</p></div><button class="btn" onclick="go('list')">+ List an item</button></div><div class="g4 mb"><div class="card"><span class="mu">Earnings</span><div class="big">${fmt(earn+2150)}</div></div><div class="card"><span class="mu">Active rentals</span><div class="big">${act.length}</div></div><div class="card"><span class="mu">Wardrobe items</span><div class="big">${mine.length}</div></div><div class="card"><span class="mu">Pending requests</span><div class="big">${req.length}</div></div></div>
${req.length?'<h3 class="mb">Pending requests</h3>'+req.map(b=>bcard(b,1)).join(''):''}${act.length?'<h3 class="mb">Active rentals & upcoming returns</h3>'+act.map(b=>bcard(b,1)).join(''):''}${done.length?'<h3 class="mb">Awaiting inspection / completed</h3>'+done.map(b=>bcard(b,1)).join(''):''}
<div class="g2 sec"><div class="card"><h3>Earnings (₹)</h3><div class="chart" style="margin:16px 0 26px">${ch.map((v,i)=>`<div style="height:${Math.max(4,v/mx*100)}%" title="${fmt(v)}"><span>${mn[i]}</span></div>`).join('')}</div><p class="mu">Impact created: ${done.length+8} reuses by your clothes.</p></div><div class="card"><h3>Wardrobe utilization</h3>${mine.map(i=>{const u=Math.min(90,(i.util||20)+bs.filter(b=>b.item==i.id).length*8);return`<div style="margin:12px 0"><div class="row sp mu"><span>${esc(i.t)}</span><b style="color:var(--ink)">${u}%</b></div><div class="bar"><i style="width:${u}%"></i></div></div>`}).join('')}</div></div>
<h3 class="mb sec">Your listings</h3><div class="grid">${mine.map(i=>`<div>${card(i)}<div class="row" style="margin-top:8px"><button class="btn s o" onclick="toggle(${i.id})">${i.off?'Make available':'Mark unavailable'}</button><button class="btn s o" onclick="simReq(${i.id})">Simulate request</button></div></div>`).join('')}</div>`}
function toggle(id){const i=S.items.find(x=>x.id==id);if(i.o!='me')return;i.off=!i.off;save();render(1)}
function simReq(id){const it=S.items.find(i=>i.id==id),s=iso(3+S.bookings.length%5),e=addd(s,1),n=['Ishaan V.','Nithya K.','Sanjay P.'][S.bookings.length%3];if(!avail(it,s,e)){toast('Choose another item — these dates are taken');return}
S.bookings.unshift({id:'RW-'+(24130+S.bookings.length),item:id,renter:n,start:s,end:e,days:2,rent:it.p*2,dep:it.d,fee:0,del:0,total:0,stage:-1,created:iso(0),rv:0,ful:'pickup'});notif(n+' requested '+it.t);toast('New request from '+n);save();render(1)}
const BASE={Saree:450,Lehenga:850,Kurta:320,Sherwani:700,Blazer:400,Suit:750,Dress:480,Gown:800,'Ethnic Wear':550,Accessories:250},CF={'Like New':1.1,Excellent:1,Good:.85,Fair:.65},DEM={Saree:'High',Lehenga:'High',Sherwani:'High',Blazer:'High',Suit:'High',Gown:'Medium',Kurta:'Medium','Ethnic Wear':'High',Dress:'Medium',Accessories:'Medium'},SO={Blazer:'Interview · Formal Event · Photoshoot',Suit:'Interview · Wedding · Formal Event',Saree:'Wedding · Festival · College Event',Lehenga:'Wedding · Festival',Sherwani:'Wedding · Festival',Kurta:'Festival · College Event',Dress:'Party · Photoshoot',Gown:'Party · Wedding · Photoshoot','Ethnic Wear':'Wedding · Festival',Accessories:'Wedding · Photoshoot'};
function sug(){const c=$('#lc').value,cd=$('#ld').value,p=Math.round(BASE[c]*CF[cd]/10)*10,dep=Math.round(p*3.3/100)*100,dm=DEM[c],r=dm=='High'?[4,6]:[2,4];$('#sg').innerHTML=`<h3>✦ Wardrobe → Income</h3><p class="mu mb">This item could earn approximately <b style="color:var(--ink)">${fmt(p)}</b> per rental day.</p><table><tr><td>Owned for</td><td align="right">${$('#lo').value} months</td></tr><tr><td>Last used</td><td align="right">${$('#lw').value} months ago</td></tr><tr><td>Suggested rental</td><td align="right"><b>${fmt(p)}/day</b></td></tr><tr><td>Suggested security deposit</td><td align="right"><b>${fmt(dep)}</b></td></tr><tr><td>Potential demand</td><td align="right"><b>${dm}</b></td></tr><tr><td>Suggested occasions</td><td align="right">${SO[c]}</td></tr></table><div class="al ok" style="margin-top:12px">Estimated monthly earning: ${fmt(p*r[0])}–${fmt(p*r[1])}<div class="mu" style="font-weight:400">Estimate based on demo assumptions (${r[0]}–${r[1]} rentals/month). Actual earnings vary.</div></div>`;$('#lp').value=p;$('#ldp').value=dep}
function listPg(){return`<div class="stp"><div class="on">1. Photos</div><div class="on">2. Details</div><div class="on">3. Price</div><div class="on">4. Publish</div></div><h2>List an item</h2><p class="mu mb">Your exact address is never shown publicly.</p><div class="g2" style="align-items:start"><div class="card"><div class="f"><div><label for="lt">Title</label><input id="lt" maxlength="60" placeholder="Black Blazer"></div><div><label for="lb">Brand</label><input id="lb" maxlength="30" placeholder="Zara"></div>${sel('lc',CATS,'Blazer','Category').replace('<select','<select onchange="sug()"')}${sel('ls',['Free',...SZ],'M','Size')}${sel('ld',['Like New','Excellent','Good','Fair'],'Excellent','Condition').replace('<select','<select onchange="sug()"')}${sel('lst',['Elegant','Traditional','Modern','Formal'],'Formal','Style')}<div><label for="lcol">Colour</label><input id="lcol" type="color" value="#1c1c1c" style="height:44px;padding:4px"></div>${sel('la',Object.keys(AREAS),S.me.area,'Pickup area')}<div><label for="lo">Owned for (months)</label><input id="lo" type="number" value="18" min="0" oninput="sug()"></div><div><label for="lw">Last used (months ago)</label><input id="lw" type="number" value="6" min="0" oninput="sug()"></div><div><label for="lp">Rental price / day (₹)</label><input id="lp" type="number" min="50"></div><div><label for="ldp">Security deposit (₹)</label><input id="ldp" type="number" min="0"></div><div><label for="lf">Available from</label><input id="lf2" type="date" min="${iso(0)}" value="${iso(0)}"></div><div><label for="lph">Photo</label><input id="lph" type="file" accept="image/*"></div></div><fieldset style="border:0;margin-top:14px"><legend style="font-weight:600;font-size:13px;margin-bottom:6px">Suitable occasions</legend><div class="row">${Object.values(OCC).map((o,i)=>`<label class="ch" style="margin:0;font-weight:500"><input type="checkbox" class="oc" value="${o}" ${i==3||i==5?'checked':''}> ${o}</label>`).join('')}</div></fieldset><div id="le2" class="err" role="alert"></div><button class="btn" style="margin-top:16px" onclick="publish()">Publish listing</button></div><div class="card" id="sg"></div></div>`}
function publish(){const v=id=>$('#'+id).value.trim(),oc=[...document.querySelectorAll('.oc:checked')].map(x=>x.value),p=+v('lp');if(!v('lt')||!v('ls')||!v('ld')||((!p||p<50)&&$('#lty').value!='sell')||($('#lty').value!='rent'&&!(+$('#lsp').value>=100))||!oc.length){$('#le2').textContent='Please add a title, size, condition, rental price (₹50+) and/or selling price (₹100+) and at least one occasion.';return}
const f=$('#lph').files[0],add=img=>{S.items.push({id:Math.max(...S.items.map(i=>i.id))+1,t:v('lt').slice(0,60),c:v('lc'),s:v('ls'),b:v('lb')||'—',col:v('lcol'),occ:oc,st:v('lst'),cd:v('ld'),clean:0,p,d:+v('ldp')||Math.round(p*3.3),area:v('la'),r:4.5,n:0,o:'me',g:'U',mrp:(p*8)||Math.round(+$('#lsp').value*2.5),blk:[],j:.6,live:1,off:0,ok:1,util:10,img,ty:$('#lty').value,sp:+$('#lsp').value||0,sold:0});notif('Your listing "'+v('lt')+'" is live');toast('Listing published 🎉');go('wardrobe')};
if(f&&f.size<400000){const r=new FileReader();r.onload=()=>add(r.result);r.readAsDataURL(f)}else add(null)}
function profile(){const pl=S.me.plus;return`<h2>Profile</h2><div class="card mb"><div class="row sp"><div><b style="font-size:18px">${esc(S.me.name)}</b><div class="mu">${esc(S.me.email)} · ${S.me.area}</div></div><div class="row"><span class="pill">✓ Identity Verified</span><span class="pill">✓ Reliable Return History</span></div></div></div><h3 class="mb">Membership</h3><div class="g2 mb"><div class="card"><h3>Free</h3><p class="mu">${S.cfg.fee}% platform fee · Standard rentals · Basic recommendations</p>${pl?`<button class="btn o s" style="margin-top:12px" onclick="S.me.plus=0;save();render(1)">Switch to Free</button>`:'<span class="pill" style="margin-top:12px">Current plan</span>'}</div><div class="card" style="border:2px solid var(--green)"><h3>CIRCLOSET Plus · ₹149/mo</h3><p class="mu">${S.cfg.feePlus}% platform fee · Priority AI recommendations · Free delivery · Early access to listings</p>${pl?'<span class="pill" style="margin-top:12px">Active ✓</span>':`<button class="btn s" style="margin-top:12px" onclick="S.me.plus=1;toast('Plus activated (mock)');save();render(1)">Upgrade (mock)</button>`}</div></div><div class="card mb"><h3>Optional services</h3><p class="mu">Doorstep delivery ${fmt(S.cfg.del)} · Professional cleaning ₹120 · Premium ID verification ₹99 — <i>revenue: rental commission, memberships and add-ons.</i></p></div><div class="card mb"><h3>Roadmap</h3><p class="mu"><b style="color:var(--ink)">MVP (this demo):</b> accounts, listings, search, explainable matching, availability, booking with mock payment, deposit workflow, reviews, dashboards, impact.<br><b style="color:var(--ink)">Future:</b> real payments & GPS, delivery partners, image recognition, size recommendation, cleaning partners, smart lockers, dynamic pricing.</p></div><div class="row"><button class="btn o" onclick="const r=document.documentElement;r.dataset.theme=r.dataset.theme=='dark'?'light':'dark'">Toggle theme</button><button class="btn o" onclick="if(prompt('Type RESET to clear demo data')=='RESET'){localStorage.removeItem('circloset1');location.reload()}">Reset demo data</button><button class="btn" onclick="S.user=null;save();render()">Sign out</button></div>`}
function admin(){const m=impactNums(),ac=S.bookings.filter(b=>b.stage>=0&&b.stage<4).length,cp=S.bookings.filter(b=>b.stage==6).length+412,rev=S.bookings.reduce((a,b)=>a+(b.stage>=0?b.fee:0),0)+38400,c=S.cfg;
return`<h2>Admin dashboard</h2><p class="mu mb">Platform operations — restricted to admin role.</p><div class="g4 mb">${[['Total users',S.users.length+1180],['Active rentals',ac+37],['Listed clothes',S.items.filter(i=>i.live).length+286],['Completed rentals',cp],['Reported issues',S.issues.filter(i=>i.st=='Open').length],['Platform revenue',fmt(rev)],['Items reused',m.n.toLocaleString('en-IN')],['Est. waste avoided',m.kg.toLocaleString('en-IN')+' kg']].map(x=>`<div class="card"><span class="mu">${x[0]}</span><div class="big">${x[1]}</div></div>`).join('')}</div>
<div class="card mb tab"><h3>Dispute & issue queue</h3><table><tr><th>Booking</th><th>Item</th><th>Reported by</th><th>Claim</th><th>Status</th><th></th></tr>${S.issues.map(i=>`<tr><td>${i.b}</td><td>${esc(i.item)}</td><td>${esc(i.by)}</td><td>${esc(i.note)}<br><b>${fmt(i.amt)}</b> of ${fmt(i.dep)}</td><td><span class="pill ${i.st=='Open'?'w':''}">${i.st}</span></td><td>${i.st=='Open'?`<button class="btn s g" onclick="resolve(${i.id},1)">Approve claim</button> <button class="btn s o" onclick="resolve(${i.id},.5)">50%</button> <button class="btn s o" onclick="resolve(${i.id},0)">Reject</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="mu">No issues reported.</td></tr>'}</table></div>
<div class="g2 mb"><div class="card tab"><h3>Users & verification</h3><table>${S.users.map(u=>`<tr><td>${esc(u.n)}<div class="mu">${u.role}</div></td><td>${u.v?'<span class="pill">Verified</span>':'<span class="pill w">Pending</span>'}</td><td>${u.v?'':`<button class="btn s" onclick="verify(${u.id})">Verify</button>`}</td></tr>`).join('')}</table></div><div class="card tab"><h3>Listing review</h3><table>${S.items.filter(i=>i.live).slice(-8).map(i=>`<tr><td>${esc(i.t)}<div class="mu">${own(i).n} · ${fmt(i.p)}/day</div></td><td><button class="btn s o" onclick="rmItem(${i.id})">Remove</button></td></tr>`).join('')}</table></div></div>
<div class="card mb tab"><h3>Recent transactions</h3><table><tr><th>Booking</th><th>Item</th><th>Total</th><th>Platform fee</th><th>Stage</th></tr>${S.bookings.filter(b=>b.stage>=0).slice(0,8).map(b=>`<tr><td>${b.id}</td><td>${esc(S.items.find(i=>i.id==b.item)?.t||'—')}</td><td>${fmt(b.total)}</td><td>${fmt(b.fee)}</td><td>${STG[b.stage]}</td></tr>`).join('')}</table></div>
<div class="card"><h3>Configuration</h3><p class="mu mb">Matching weights and impact factors are configurable.</p><div class="f">${Object.keys(c.w).map(k=>`<div><label for="w${k}">${k} weight %</label><input id="w${k}" type="number" min="0" max="100" value="${c.w[k]}" onchange="S.cfg.w['${k}']=+this.value;save()"></div>`).join('')}<div><label for="ck">kg textile / rental</label><input id="ck" type="number" step="0.1" value="${c.kg}" onchange="S.cfg.kg=+this.value;save()"></div><div><label for="cw">Litres water / rental</label><input id="cw" type="number" value="${c.water}" onchange="S.cfg.water=+this.value;save()"></div><div><label for="cf">Platform fee %</label><input id="cf" type="number" value="${c.fee}" onchange="S.cfg.fee=+this.value;save()"></div></div></div>`}
function resolve(id,pct){const i=S.issues.find(x=>x.id==id),ded=Math.round(i.amt*pct);i.st='Resolved';i.res=ded;const b=S.bookings.find(x=>x.id==i.b);if(b){b.hold=ded;b.stage=6;b.issue=0}notif('Dispute '+i.b+' resolved: '+fmt(ded)+' deducted, '+fmt(i.dep-ded)+' refunded');toast('Deposit adjusted: '+fmt(i.dep-ded)+' refunded');save();render(1)}
function verify(id){S.users.find(u=>u.id==id).v=1;toast('User verified');save();render(1)}
function rmItem(id){const i=S.items.find(x=>x.id==id);i.live=0;toast('Listing removed');save();render(1)}
